func parseNum(field string, scale int32) decimal.Decimal {
	s := strings.TrimSpace(field)
	if s == "" {
		return decimal.Zero
	}
	neg := false
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		if strings.HasPrefix(s, "-") {
			neg = true
		}
		s = s[1:]
	}
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	d := digits
	// strip leading zeros for big int parse but keep at least one
	n, ok := parseInt64(digits)
	_ = d
	var dec decimal.Decimal
	if ok {
		dec = decimal.New(n, -scale)
		// if digits longer than int64, fallback via string
		if len(digits) > 18 {
			dec2, err := decimal.NewFromString(digits)
			if err == nil {
				dec = dec2.Shift(-scale)
			}
		}
	} else {
		dec2, err := decimal.NewFromString(digits)
		if err == nil {
			dec = dec2.Shift(-scale)
		} else {
			dec = decimal.Zero
		}
	}
	if neg {
		dec = dec.Neg()
	}
	return dec
}

func parseInt64(digits string) (int64, bool) {
	var n int64
	if len(digits) > 18 {
		return 0, false
	}
	for _, ch := range digits {
		n = n*10 + int64(ch-'0')
	}
	return n, true
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// store helpers: truncate toward zero then mod low-order digits
func storeScaled(v decimal.Decimal, scale int32, mod int64) decimal.Decimal {
	t := v.Truncate(scale)
	sc := t.Shift(scale).Truncate(0).IntPart()
	m := sc % mod
	if m < 0 {
		m += mod
		// COBOL unsigned keeps magnitude? keep simple mod
		// sign handling: for negative, low-order with sign? ignore
	}
	return decimal.New(m, -scale)
}

func storeV9(v decimal.Decimal) decimal.Decimal {
	return storeScaled(v, 1, 10000)
}
func storeV99_7(v decimal.Decimal) decimal.Decimal {
	return storeScaled(v, 2, 1000000000)
}
func storeDeptTotal(v decimal.Decimal) decimal.Decimal {
	return storeScaled(v, 2, 100000000000)
}
func storeGrandTotal(v decimal.Decimal) decimal.Decimal {
	return storeScaled(v, 2, 10000000000000)
}

func formatEdited(absVal decimal.Decimal, intTypes []bool, decScale int) (string, string) {
	// intTypes: false=Z, true=9 ; len N
	N := len(intTypes)
	scaled := absVal.Abs().Shift(int32(decScale)).Round(0).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	pow10 := func(e int) int64 {
		r := int64(1)
		for i := 0; i < e; i++ {
			r *= 10
		}
		return r
	}
	fracMod := pow10(decScale)
	var frac int64
	var intPart int64
	if decScale > 0 {
		frac = scaled % fracMod
		intPart = scaled / fracMod
	} else {
		frac = 0
		intPart = scaled
	}
	modInt := pow10(N)
	intPart = intPart % modInt
	digits := make([]int, N)
	for i := N - 1; i >= 0; i-- {
		digits[i] = int(intPart % 10)
		intPart /= 10
	}
	fracDigits := make([]int, decScale)
	for i := decScale - 1; i >= 0; i-- {
		fracDigits[i] = int(frac % 10)
		frac /= 10
	}
	firstNZ := N
	for i := 0; i < N; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	_ = fracDigits
	_ = firstNZ
	return strings.Repeat(" ", 0), ""
}

func pow10int(e int) int64 {
	r := int64(1)
	for i := 0; i < e; i++ {
		r *= 10
	}
	return r
}

func buildEdited(v decimal.Decimal, pic string, intTypes []bool, decScale int) string {
	N := len(intTypes)
	scaled := v.Abs().Shift(int32(decScale)).Round(0).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	var fracMod int64 = 1
	for i := 0; i < decScale; i++ {
		fracMod *= 10
	}
	var frac, intPart int64
	if decScale > 0 {
		frac = scaled % fracMod
		intPart = scaled / fracMod
	} else {
		intPart = scaled
	}
	intPart = intPart % pow10int(N)
	digits := make([]int, N)
	tmp := intPart
	for i := N - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	fracDigits := make([]int, decScale)
	tmpf := frac
	for i := decScale - 1; i >= 0; i-- {
		fracDigits[i] = int(tmpf % 10)
		tmpf /= 10
	}
	firstNZ := N
	for i := 0; i < N; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var sb strings.Builder
	digitIdx := 0
	fracIdx := 0
	seenDot := false
	for _, ch := range pic {
		switch ch {
		case 'Z', '9':
			isNine := (ch == '9')
			var out byte
			if !isNine && digitIdx < firstNZ {
				out = ' '
			} else {
				out = byte('0' + digits[digitIdx])
			}
			sb.WriteByte(out)
			digitIdx++
		case ',':
			// suppressed if all int digits to left are suppressed
			// i.e., digitIdx <= firstNZ
			if digitIdx <= firstNZ {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		case '.':
			sb.WriteByte('.')
			seenDot = true
			_ = seenDot
		default:
			sb.WriteByte(byte(ch))
		}
	}
	// Now need to fill fractional digits (9s after dot)
	// Our loop above treated fractional 9s as integer digits incorrectly.
	// Rebuild correctly: handle fractional part separately.
	// Simpler: reconstruct by splitting pic at dot.
	_ = fracIdx
	return sb.String()
}

// Correct edited formatter splitting integer/fraction pictures
func fmtEdited(v decimal.Decimal, intTypes []bool, decScale int, useComma1 bool, useComma2 bool, kind int) string {
	// kind: 0=hours ZZ9.9, 1=rate ZZ9.99, 2=gross Z,ZZZ,ZZ9.99, 3=dept ZZZ,ZZZ,ZZ9.99, 4=grand ZZ,ZZZ,ZZZ,ZZ9.99
	N := len(intTypes)
	scaled := v.Abs().Shift(int32(decScale)).Round(0).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	fracMod := pow10int(decScale)
	var frac, intPart int64
	if decScale > 0 {
		frac = scaled % fracMod
		intPart = scaled / fracMod
	} else {
		intPart = scaled
	}
	intPart = intPart % pow10int(N)
	digits := make([]int, N)
	t := intPart
	for i := N - 1; i >= 0; i-- {
		digits[i] = int(t % 10)
		t /= 10
	}
	fracDigits := make([]int, decScale)
	tf := frac
	for i := decScale - 1; i >= 0; i-- {
		fracDigits[i] = int(tf % 10)
		tf /= 10
	}
	firstNZ := N
	for i := 0; i < N; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	intSuppressed := func(idx int) bool {
		// digit idx suppressed?
		return idx < firstNZ && !intTypes[idx]
	}
	_ = intSuppressed
	switch kind {
	case 0: // ZZ9.9 -> 5 chars
		var b [5]byte
		for i := 0; i < 3; i++ {
			if i < firstNZ && !intTypes[i] {
				b[i] = ' '
			} else {
				b[i] = byte('0' + digits[i])
			}
		}
		b[3] = '.'
		b[4] = byte('0' + fracDigits[0])
		return string(b[:])
	case 1: // ZZ9.99
		var b [6]byte
		for i := 0; i < 3; i++ {
			if i < firstNZ && !intTypes[i] {
				b[i] = ' '
			} else {
				b[i] = byte('0' + digits[i])
			}
		}
		b[3] = '.'
		b[4] = byte('0' + fracDigits[0])
		b[5] = byte('0' + fracDigits[1])
		return string(b[:])
	case 2: // Z,ZZZ,ZZ9.99 len12
		// layout: d0 , d1 d2 d3 , d4 d5 d6 . f0 f1
		out := make([]byte, 12)
		// positions: 0:d0 1:, 2:d1 3:d2 4:d3 5:, 6:d4 7:d5 8:d6 9:. 10:f0 11:f1
		dpos := []int{0, 2, 3, 4, 6, 7, 8}
		for k, p := range dpos {
			idx := k
			if idx < firstNZ && !intTypes[idx] {
				out[p] = ' '
			} else {
				out[p] = byte('0' + digits[idx])
			}
		}
		if 1 <= firstNZ {
			out[1] = ' '
		} else {
			out[1] = ','
		}
		if 4 <= firstNZ {
			out[5] = ' '
		} else {
			out[5] = ','
		}
		out[9] = '.'
		out[10] = byte('0' + fracDigits[0])
		out[11] = byte('0' + fracDigits[1])
		return string(out)
	case 3: // ZZZ,ZZZ,ZZ9.99 len14
		// d0 d1 d2 , d3 d4 d5 , d6 d7 d8 . f0 f1
		out := make([]byte, 14)
		dpos := []int{0, 1, 2, 4, 5, 6, 8, 9, 10}
		for k, p := range dpos {
			idx := k
			if idx < firstNZ && !intTypes[idx] {
				out[p] = ' '
			} else {
