		} else {
			out[3] = ','
		}
		if 6 <= firstNZ {
			out[7] = ' '
		} else {
			out[7] = ','
		}
		out[11] = '.'
		out[12] = byte('0' + fracDigits[0])
		out[13] = byte('0' + fracDigits[1])
		return string(out)
	case 4: // ZZ,ZZZ,ZZZ,ZZ9.99 len17
		// d0 d1 , d2 d3 d4 , d5 d6 d7 , d8 d9 d10 . f0 f1
		out := make([]byte, 17)
		dpos := []int{0, 1, 3, 4, 5, 7, 8, 9, 11, 12, 13}
		for k, p := range dpos {
			idx := k
			if idx < firstNZ && !intTypes[idx] {
