		}
		if 5 <= firstNZ {
			out[6] = ' '
		} else {
			out[6] = ','
		}
		if 8 <= firstNZ {
			out[10] = ' '
		} else {
			out[10] = ','
		}
		out[14] = '.'
		out[15] = byte('0' + fracDigits[0])
		out[16] = byte('0' + fracDigits[1])
		return string(out)
	}
	return ""
}

