func fmtCount3(n int64) string {
	m := n % 1000
	if m < 0 {
		m += 1000
	}
	return fmt.Sprintf("%03d", m)
}
func fmtCount5(n int64) string {
	m := n % 100000
	if m < 0 {
		m += 100000
	}
	return fmt.Sprintf("%05d", m)
}

func MainPara() {
	openInput()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	closeInput()
	GrandPara()
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		inputLines = nil
		inputIdx = 0
		inputOpen = false
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for sc.Scan() {
		line := sc.Text()
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		lines = append(lines, line)
	}
	inputLines = lines
	inputIdx = 0
	inputOpen = true
}
func closeInput() {}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	empRec.ErId = line[0:5]
	empRec.ErDept = line[5:8]
	empRec.ErHours = parseNum(line[8:12], 1)
	empRec.ErRate = parseNum(line[12:17], 2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = empRec.ErDept
		WsFirstFlag = "N"
	} else {
		if empRec.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = empRec.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if empRec.ErHours.GreaterThan(forty) {
		WsRegHours = storeV9(decimal.NewFromInt(40))
		WsOtHours = storeV9(empRec.ErHours.Sub(forty).Truncate(1))
	} else {
		WsRegHours = storeV9(empRec.ErHours.Truncate(1))
		WsOtHours = storeV9(decimal.Zero)
	}
	onePointFive := decimal.New(15, -1)
	comp := WsRegHours.Mul(empRec.ErRate).Add(WsOtHours.Mul(empRec.ErRate).Mul(onePointFive))
	WsGross = storeScaled(comp.Round(2), 2, 1000000000)
	WsDeptTotal = storeDeptTotal(WsDeptTotal.Add(WsGross))
	WsDeptCount = (WsDeptCount + 1) % 1000
	WsGrandTotal = storeGrandTotal(WsGrandTotal.Add(WsGross))
	WsGrandCount = (WsGrandCount + 1) % 100000
	WsHoursEd = fmtHours(empRec.ErHours)
	WsRateEd = fmtRate(empRec.ErRate)
	WsGrossEd = fmtGross(WsGross)
	fmt.Println(empRec.ErId+" "+empRec.ErDept+" "+WsHoursEd+" "+WsRateEd+" "+WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = fmtDept(WsDeptTotal)
	fmt.Println("  DEPT "+WsPrevDept+" EMPLOYEES: "+fmtCount3(WsDeptCount)+" TOTAL: "+WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = fmtGrand(WsGrandTotal)
	fmt.Println("GRAND TOTAL ("+fmtCount5(WsGrandCount)+"): "+WsGrandEd)
}

